'use client'

import { useState } from 'react'
import { FaWhatsapp, FaInstagram, FaStar } from 'react-icons/fa'

export default function Contato() {
  const [nome, setNome] = useState('')
  const [motivo, setMotivo] = useState('')

  const handleEnviarWhatsApp = (e: React.FormEvent) => {
    e.preventDefault() // Evita que a página recarregue
    const numero = "5516981010674"
    const mensagem = `Olá Arthur! Meu nome é ${nome} e gostaria de agendar uma avaliação. O motivo/dor principal é: ${motivo}.`
    
    // Codifica a mensagem para o formato de link e abre o WhatsApp
    const url = `https://wa.me/${numero}?text=${encodeURIComponent(mensagem)}`
    window.open(url, '_blank')
  }

  return (
    <section id="contato" className="py-16 md:py-24 border-t border-brand-red/20">
      <div className="bg-brand-black rounded-2xl p-8 md:p-12 shadow-2xl flex flex-col lg:flex-row gap-12">
        
        {/* Lado Esquerdo: Formulário */}
        <div className="flex-1">
          <h2 className="text-3xl md:text-4xl font-bold text-white mb-4">
            Pronto para agendar sua <span className="text-brand-red">Sessão</span>?
          </h2>
          <p className="text-brand-beige/80 text-lg mb-8">
            Preencha os dados abaixo e o Arthur receberá sua mensagem diretamente no WhatsApp para agilizar seu atendimento.
          </p>

          <form onSubmit={handleEnviarWhatsApp} className="space-y-6">
            <div>
              <label htmlFor="nome" className="block text-brand-beige/90 text-sm font-medium mb-2">
                Seu Nome
              </label>
              <input
                type="text"
                id="nome"
                required
                value={nome}
                onChange={(e) => setNome(e.target.value)}
                className="w-full bg-white/10 border border-white/20 rounded-md px-4 py-3 text-white placeholder-white/30 focus:outline-none focus:border-brand-red transition-colors"
                placeholder="Ex: João Silva"
              />
            </div>
            
            <div>
              <label htmlFor="motivo" className="block text-brand-beige/90 text-sm font-medium mb-2">
                Onde dói? / Motivo da consulta
              </label>
              <textarea
                id="motivo"
                required
                rows={3}
                value={motivo}
                onChange={(e) => setMotivo(e.target.value)}
                className="w-full bg-white/10 border border-white/20 rounded-md px-4 py-3 text-white placeholder-white/30 focus:outline-none focus:border-brand-red transition-colors resize-none"
                placeholder="Ex: Muita dor na lombar há 3 meses..."
              />
            </div>

            <button
              type="submit"
              className="w-full bg-brand-red text-white font-bold py-4 rounded-md hover:bg-red-800 transition-colors flex justify-center items-center gap-2 shadow-lg"
            >
              <FaWhatsapp className="text-2xl" />
              Enviar pelo WhatsApp
            </button>
          </form>
        </div>

        {/* Lado Direito: Informações Diretas */}
        <div className="flex-1 flex flex-col justify-center gap-8 lg:pl-12 lg:border-l border-white/10 mt-8 lg:mt-0">
          
          {/* WhatsApp Direto */}
          <div className="flex items-center gap-5">
            <div className="bg-brand-red p-4 rounded-full shadow-lg shrink-0">
              <FaWhatsapp className="text-2xl text-white" />
            </div>
            <div>
              <h3 className="font-bold text-lg text-white">Contato Direto</h3>
              <p className="text-brand-beige/80">(16) 98101-0674</p>
            </div>
          </div>

          {/* Instagram */}
          <div className="flex items-center gap-5">
            <div className="bg-brand-red p-4 rounded-full shadow-lg shrink-0">
              <FaInstagram className="text-2xl text-white" />
            </div>
            <div>
              <h3 className="font-bold text-lg text-white">Instagram</h3>
              <p className="text-brand-beige/80">@arthurfelipe_terapias_</p>
            </div>
          </div>

          {/* Avaliações */}
          <div className="flex items-center gap-5">
            <div className="bg-brand-red p-4 rounded-full shadow-lg shrink-0">
              <FaStar className="text-2xl text-white" />
            </div>
            <div>
              <h3 className="font-bold text-lg text-white">Avaliações</h3>
              <p className="text-brand-beige/80">5,0 ⭐ no Google</p>
              <p className="text-brand-red text-sm mt-1 italic font-medium">"O melhor de Ribeirão e região"</p>
            </div>
          </div>

        </div>
      </div>
    </section>
  )
}